Script.script:
Clases.guerrero = {
  ataque = function(obj)
    send("mata " .. obj)
    send("espi")
  end,
  recall = function()
    Clases.sendSeq("s", "s", "e", "e", "s", "e", "s")
  end,
  -- Sin lista de fabrica (CMUD no tenia dope para esta clase). Queda vacia
  -- hasta que uses "addspell" -- asi el comando "dope" funciona apenas
  -- agregues el primer hechizo, sin tener que tocar el paquete.
  dope = function(obj)
    Clases.dopar(Clases.dopes.guerrero, obj)
  end,
}

Clases.ladron = {
  ataque = function(obj)
    send("robar oro " .. obj)
    send("esconder")
    send("ocultar")
  end,
  engancha = function(obj)
    send("co " .. obj)
  end,
  recall = function()
    Clases.sendSeq("s", "s", "s", "e", "s", "e", "s")
  end,
  dope = function(obj)
    Clases.dopar(Clases.dopes.ladron, obj)
  end,
}

-- Lista de fabrica (original de CMUD, var StringList "dopesranger").
Clases.dopes.ranger = Clases.dopes.ranger or {
  "volar", "niebla", "piel", "espiritu", "bendecir",
  "detectar invisibilidad", "totem animal buho",
}

Clases.ranger = {
  ataque = function(obj)
    send("c raices " .. obj)
  end,
  engancha = function(obj)
    send("c raices " .. obj)
  end,
  recall = function()
    Clases.sendSeq("s", "nore", "n", "w")
  end,
  dope = function(obj)
    Petria.traga("santu")
    send("c anti bolsillo")
    send("fuego")
    send("c 'totem animal buho'")
    Clases.dopar(Clases.dopes.ranger, obj)
  end,
}

-- Lista de fabrica del druida normal (buffs de "slist druida"). Los que aun
-- no tienes por nivel dan "No conoces ningun hechizo" y se ignoran; se puede
-- ajustar con los alias de dope como en las otras clases.
Clases.dopes.druida = Clases.dopes.druida or {
  "proteccion", "buen aura", "bendecir", "detectar invisibilidad",
  "antifuego", "gatovision", "piel de corteza", "volar", "fuerza colosal",
  "proteccion divina", "acelerar", "santuario",
}

Clases.druida = {
  ataque = function(obj)
    send("mata " .. obj)
    send("c rayo")
  end,
  recall = function()
    Clases.sendSeq("s", "suro")
  end,
  dope = function(obj)
    Clases.dopar(Clases.dopes.druida, obj)
  end,
}
